def is_regular_bracket_sequence(seq):
    balance = 0
    for char in seq:
        if char == '(':
            balance += 1
        elif char == ')':
            balance -= 1
        if balance < 0:
            return False
    return balance == 0

def merge_sequences(s, t):
    # Create a stack to keep track of unmatched '('
    stack = []
    result = []

    # Process the first sequence s
    for char in s:
        if char == '(':
            stack.append(char)
        else:
            if stack:
                stack.pop()
            else:
                result.append(char)

    # Process the second sequence t
    for char in t:
        if char == '(':
            stack.append(char)
        else:
            if stack:
                stack.pop()
            else:
                result.append(char)

        # Add unmatched '(' from stack to result
        while stack:
            result.append(')')
            stack.pop()

    # Add remaining unmatched '(' to result
    result.extend(['('] * len(stack))

    # Convert list to string
    return ''.join(result)

